SELECT order_id, delivery_time_minutes
FROM orders
WHERE delivery_time_minutes > 40;

SELECT order_id, customer_id, delivery_time_minutes
FROM orders
WHERE (customer_id = 1 OR customer_id = 2) AND delivery_time_minutes > 30;

SELECT order_id, delivery_time_minutes
FROM orders
WHERE delivery_time_minutes IS NULL;

SELECT order_id, delivery_time_minutes
FROM orders
WHERE delivery_time_minutes IS NOT NULL;

SELECT order_id, region
FROM orders
ORDER BY region ASC, order_id DESC;

SELECT order_id,
       CAST(amount AS TEXT) AS amount_text
  FROM orders AS o;
SELECT order_id,
       amount::TEXT AS amount_text
  FROM orders AS o;

